assert "1142" not in vis.replace("ת\"י 1142 עוסק במעקים ומסעדים", "").replace("לא לפי ת\"י 1142", ""), "1142 only as the correction"
words = len(re.findall(r"[\w֐-׿\"']+", vis))
print("[term %d] %d words, %d tables, %d FAQ, title %d chars, desc %d chars" % (PID, words, NEW.count("<table"), len(QA), len(TITLE), len(DESC)))
